// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n//  SECCI\u00d3N 5 \u2014 ESTAD\u00cdSTICAS: \ud83d\udcc5 TURNOS\n// \u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\u2550\n\n/**\n * ESTADISTICAS_TURNOS\n * Agrega secci\u00f3n de estad\u00edsticas al lado derecho de la hoja Turnos.\n * Columna de inicio: 14 (N) \u2014 con separador en col 13\n */\nfunction ESTADISTICAS_TURNOS() {\n  var ss = SpreadsheetApp.getActiveSpreadsheet();\n  var sh = ss.getSheetByName(HOJA_TURNOS_E);\n  if (!sh) {\n    Logger.log(\"ERROR: No se encontr\u00f3 la hoja Turnos.\");\n    return;\n  }\n\n  var colSep   = 14;  // N \u2014 separador\n  var colStats = 15;  // O \u2014 inicio estad\u00edsticas\n  var nCols    = 8;\n\n  var colNec = colStats + nCols + 1;\n  if (sh.getMaxColumns() < colNec) {\n    sh.insertColumnsAfter(sh.getMaxColumns(), colNec - sh.getMaxColumns());\n    SpreadsheetApp.flush(); Utilities.sleep(400);\n  }\n\n  sh.setColumnWidth(colSep, 18);\n  [180, 120, 120, 100, 100, 100, 100, 100].forEach(function(w, i) {\n    sh.setColumnWidth(colStats + i, w);\n  });\n\n  // Rangos base\n  var R0 = FILA_TURNOS_E;\n  var R1 = R0 + MAX_TURNOS_E - 1;\n  var rA  = \"A\" + R0 + \":A\" + R1;  // Fechas\n  var rE  = \"E\" + R0 + \":E\" + R1;  // Duraci\u00f3n\n  var rG  = \"G\" + R0 + \":G\" + R1;  // Es e